/********************************************** 
 * 함수명   : Print(dtsObj)
 * 설명       : 연부과금 화면을 인쇄한다.(유가) 
 ***********************************************/
/**
 * @method
 * @name fn_pre_print_stock
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} chk_test desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_pre_print_stock = function(dtsObj, chk_test) {
    dts_Print.SetDataHeader("genealChief:STRING(80)" + ",chgEmp:STRING(80)" + ",anulfeeNotiImpostNo:STRING(20)" + ",anulfeeEnforceDd:STRING(20)" + ",send:STRING(200)" + ",reference__STRING(200)" + ",basYyStr:STRING(200)" + ",basYy:STRING(10)" + ",stkcertAnulfee__decimal(20)" + ",benfcertAnulfee__decimal(20)" + ",subsrghtAnulfee__decimal(20)" + ",elwAnulfee__decimal(20)" + ",anulfeeTotal:decimal(20)" + ",payDeadlineDd:STRING(20)" + ",anulfeePayMethdDsc:STRING(1000)" + ",cap:decimal(20)" + ",paySnulfee__STRING(20)" + ",remk:STRING(2000)" + "");
    if (chk_test == true) {
        dts_Print.AddRow();
        dts_Print.setCellData(1, "genealChief", dtsObj.getCellData(1, "GENEAL_CHIEF"));
        dts_Print.setCellData(1, "chgEmp", dtsObj.getCellData(1, "CHG_EMP"));
        dts_Print.setCellData(1, "anulfeeNotiImpostNo", dtsObj.getCellData(1, "ANULFEE_NOTI_IMPOST_NO"));
        dts_Print.setCellData(1, "anulfeeEnforceDd", dtsObj.getCellData(1, "ANULFEE_ENFORCE_DD"));
        dts_Print.setCellData(1, "send", dtsObj.getCellData(1, "SEND"));
        dts_Print.setCellData(1, "reference", dtsObj.getCellData(1, "REFERENCE"));
        dts_Print.setCellData(1, "basYyStr", dtsObj.getCellData(1, "BAS_YY") + "년도 연부과금 부과통지");
        dts_Print.setCellData(1, "basYy", dtsObj.getCellData(1, "BEFOREYY"));
        dts_Print.setCellData(1, "stkcertAnulfee", dtsObj.getCellData(1, "STKCERT_ANULFEE"));
        dts_Print.setCellData(1, "benfcertAnulfee", dtsObj.getCellData(1, "BENFCERT_ANULFEE"));
        dts_Print.setCellData(1, "subsrghtAnulfee", dtsObj.getCellData(1, "SUBSRGHT_ANULFEE"));
        dts_Print.setCellData(1, "elwAnulfee", dtsObj.getCellData(1, "ELW_ANULFEE"));
        dts_Print.setCellData(1, "anulfeeTotal", dtsObj.getCellData(1, "ANULFEE_TOTAL"));
        dts_Print.setCellData(1, "payDeadlineDd", dtsObj.getCellData(1, "PAY_DEADLINE_DD"));
        dts_Print.setCellData(1, "anulfeePayMethdDsc", dtsObj.getCellData(1, "ANULFEE_PAY_METHD_DSC"));
        dts_Print.setCellData(1, "cap", dtsObj.getCellData(1, "CAP"));
        dts_Print.setCellData(1, "paySnulfee", dtsObj.getCellData(1, "PAY_ANULFEE"));
        dts_Print.setCellData(1, "remk", dtsObj.getCellData(1, "REMK"));
    } else {
        for (i = 1; i <= dtsObj.getTotalRow(); i++) {
            dts_Print.AddRow();
            dts_Print.setCellData(i, "genealChief", dtsObj.getCellData(i, "GENEAL_CHIEF"));
            dts_Print.setCellData(i, "chgEmp", dtsObj.getCellData(i, "CHG_EMP"));
            dts_Print.setCellData(i, "anulfeeNotiImpostNo", dtsObj.getCellData(i, "ANULFEE_NOTI_IMPOST_NO"));
            dts_Print.setCellData(i, "anulfeeEnforceDd", dtsObj.getCellData(i, "ANULFEE_ENFORCE_DD"));
            dts_Print.setCellData(i, "send", dtsObj.getCellData(i, "SEND"));
            dts_Print.setCellData(i, "reference", dtsObj.getCellData(i, "REFERENCE"));
            dts_Print.setCellData(i, "basYyStr", dtsObj.getCellData(i, "BAS_YY") + "년도 연부과금 부과통지");
            dts_Print.setCellData(i, "basYy", dtsObj.getCellData(i, "BEFOREYY"));
            dts_Print.setCellData(i, "stkcertAnulfee", dtsObj.getCellData(i, "STKCERT_ANULFEE"));
            dts_Print.setCellData(i, "benfcertAnulfee", dtsObj.getCellData(i, "BENFCERT_ANULFEE"));
            dts_Print.setCellData(i, "subsrghtAnulfee", dtsObj.getCellData(i, "SUBSRGHT_ANULFEE"));
            dts_Print.setCellData(i, "elwAnulfee", dtsObj.getCellData(i, "ELW_ANULFEE"));
            dts_Print.setCellData(i, "anulfeeTotal", dtsObj.getCellData(i, "ANULFEE_TOTAL"));
            dts_Print.setCellData(i, "payDeadlineDd", dtsObj.getCellData(i, "PAY_DEADLINE_DD"));
            dts_Print.setCellData(i, "anulfeePayMethdDsc", dtsObj.getCellData(i, "ANULFEE_PAY_METHD_DSC"));
            dts_Print.setCellData(i, "cap", dtsObj.getCellData(i, "CAP"));
            dts_Print.setCellData(i, "paySnulfee", dtsObj.getCellData(i, "PAY_ANULFEE"));
            dts_Print.setCellData(i, "remk", dtsObj.getCellData(i, "REMK"));
        }
    }

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    //var rex_rptname = "RLDSTF00019";
    var rex_rptname = "RLDFIL00007";

    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, dtsObj);
};


/********************************************** 
 * 함수명   : Print(dtsObj)
 * 설명       : 연부과금 화면을 인쇄한다.(코스닥) 
 ***********************************************/
/**
 * @method
 * @name fn_pre_print_kosdaq
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} chk_test desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_pre_print_kosdaq = function(dtsObj, chk_test) {
    dts_Print.SetDataHeader("genealChief:STRING(80)" + ",chgEmp:STRING(80)" + ",email:STRING(50)" + ",anulfeeNotiImpostNo:STRING(10)" + ",anulfeeEnforceDd:STRING(20)" + ",passage__STRING(10)" + ",todayStr:STRING(200)" + ",today:STRING(10)" + ",cap:decimal(20)" + ",anulfeeTotal:decimal(20)" + ",payDeadlineDd:STRING(20)" + ",bank:STRING(2000)" + ",send:STRING(200)" + ",basYy:STRING(10)" + "");
    if (chk_test == true) {
        dts_Print.AddRow();
        dts_Print.setCellData(1, "genealChief", dtsObj.getCellData(1, "GENEAL_CHIEF"));
        dts_Print.setCellData(1, "chgEmp", dtsObj.getCellData(1, "CHG_EMP"));
        dts_Print.setCellData(1, "email", dtsObj.getCellData(1, "EMAIL"));
        dts_Print.setCellData(1, "anulfeeNotiImpostNo", dtsObj.getCellData(1, "ANULFEE_NOTI_IMPOST_NO"));
        dts_Print.setCellData(1, "anulfeeEnforceDd", dtsObj.getCellData(1, "ANULFEE_ENFORCE_DD"));
        dts_Print.setCellData(1, "passage", dtsObj.getCellData(1, "PASSAGE"));
        dts_Print.setCellData(1, "todayStr", dtsObj.getCellData(1, "BAS_YY") + "년 연부과금 납부 안내");
        dts_Print.setCellData(1, "today", dtsObj.getCellData(1, "TODAY"));
        dts_Print.setCellData(1, "cap", dtsObj.getCellData(1, "CAP"));
        dts_Print.setCellData(1, "anulfeeTotal", dtsObj.getCellData(1, "ANULFEE_TOTAL"));
        dts_Print.setCellData(1, "payDeadlineDd", dtsObj.getCellData(1, "PAY_DEADLINE_DD"));
        dts_Print.setCellData(1, "bank", dtsObj.getCellData(1, "ANULFEE_PAY_METHD_DSC"));
        dts_Print.setCellData(1, "send", dtsObj.getCellData(1, "SEND"));
        dts_Print.setCellData(1, "basYy", dtsObj.getCellData(1, "BEFOREYY"));
    } else {
        for (i = 1; i <= dtsObj.getTotalRow(); i++) {
            dts_Print.AddRow();
            dts_Print.setCellData(i, "genealChief", dtsObj.getCellData(i, "GENEAL_CHIEF"));
            dts_Print.setCellData(i, "chgEmp", dtsObj.getCellData(i, "CHG_EMP"));
            dts_Print.setCellData(i, "email", dtsObj.getCellData(i, "EMAIL"));
            dts_Print.setCellData(i, "anulfeeNotiImpostNo", dtsObj.getCellData(i, "ANULFEE_NOTI_IMPOST_NO"));
            dts_Print.setCellData(i, "anulfeeEnforceDd", dtsObj.getCellData(i, "ANULFEE_ENFORCE_DD"));
            dts_Print.setCellData(i, "passage", dtsObj.getCellData(i, "PASSAGE"));
            dts_Print.setCellData(i, "todayStr", dtsObj.getCellData(i, "BAS_YY") + "년 연부과금 납부 안내");
            dts_Print.setCellData(i, "today", dtsObj.getCellData(i, "TODAY"));
            dts_Print.setCellData(i, "cap", dtsObj.getCellData(i, "CAP"));
            dts_Print.setCellData(i, "anulfeeTotal", dtsObj.getCellData(i, "ANULFEE_TOTAL"));
            dts_Print.setCellData(i, "payDeadlineDd", dtsObj.getCellData(i, "PAY_DEADLINE_DD"));
            dts_Print.setCellData(i, "bank", dtsObj.getCellData(i, "ANULFEE_PAY_METHD_DSC"));
            dts_Print.setCellData(i, "send", dtsObj.getCellData(i, "SEND"));
            dts_Print.setCellData(i, "basYy", dtsObj.getCellData(i, "BEFOREYY"));
        }
    }


    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    //var rex_rptname = "RLDSTF00020";
    var rex_rptname = "RLDFIL00008";

    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, dtsObj);
};
